use vstd::prelude::*;

verus! {

fn nanmin(a: Vec<i8>) -> (result: i8)
    requires
        a.len() > 0,
    ensures
        // result is some element of the array
        exists|k: int| 0 <= k < a.len() && result == a[k],
        // result is <= every element
        forall|k: int| 0 <= k < a.len() ==> (result as int) <= (a[k] as int),
{
    let mut m: i8 = a[0];
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            // m is one of the elements seen so far
            exists|k: int| 0 <= k < i && m == a[k],
            // m is <= all elements seen so far
            forall|k: int| 0 <= k < i ==> (m as int) <= (a[k] as int),
        decreases a.len() - i,
    {
        if a[i] < m {
            m = a[i];
        }
        i += 1;
    }

    result = m;
}

} // verus!